<?php
declare(strict_types=1);require_once __DIR__.'/_bootstrap.php';$customers=$db->query("SELECT cliente_email,MAX(cliente_nombre) nombre,MAX(cliente_telefono) telefono,COUNT(*) pedidos,SUM(total) valor,MAX(creado_en) ultima_compra FROM pedidos GROUP BY cliente_email ORDER BY ultima_compra DESC")->fetchAll();adminStart('Clientes');?><p class="muted">Sin cuentas de cliente: esta vista se construye a partir de los pedidos de checkout invitado.</p><div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Teléfono</th><th>Pedidos</th><th>Valor histórico</th><th>Última compra</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><strong><?=Security::e($c['nombre'])?></strong><div class="muted"><?=Security::e($c['cliente_email'])?></div></td><td><?=Security::e($c['telefono'])?></td><td><?=(int)$c['pedidos']?></td><td>$<?=number_format((float)$c['valor'],0)?></td><td><?=Security::e($c['ultima_compra'])?></td></tr><?php endforeach;?></tbody></table></div><?php adminEnd();?>
